                                  }
                                ],
                                "op": "neighbors"
                              }
                            ],
                            "op": "intersection"
                          }
                        ],
                        "op": "induced_edges"
                      }
                    ],
                    "op": "edge_min_weight_sum"
                  }
                ],
                "op": "sub"
              }
            ],
            "op": "max"
          },
          "name": "neighbor_pair_floor"
        }
      ],
      "name": "local_pair_opportunity",
      "rationale": "Penalizes jointly collectible conflicts using a weighted edge-deletion lower bound and the heaviest neighbor. Reach is limited to active one-hop neighbors, so the distant cycle remains unresolved; neighbor edge construction can be quadratic in degree.",
      "rule": "weight - 0.5 * max(max_conflict_weight, neighbor_pair_floor) + 0.08 * weight / (1 + max(0, degree))"
    },
    {
      "features": [
        {
          "expression": {
            "args": [
