              }
            ],
            "op": "greedy_independent_weight"
          },
          "name": "neighbor_greedy_weight"
        },
        {
          "expression": {
            "args": [
              {
                "args": [
                  {
                    "args": [],
                    "op": "available"
                  },
                  {
                    "args": [
                      {
                        "args": [],
                        "op": "root"
                      }
                    ],
                    "op": "neighbors"
                  }
                ],
                "op": "intersection"
              }
            ],
            "op": "clique_cover_weight"
          },
          "name": "neighbor_cover_weight"
        }
      ],
      "name": "local_collectible_ratio",
      "rationale": "Normalizes reward by a blend of feasible greedy and cover estimates of collectible neighboring weight, with a small duration-efficiency term. Both estimates remain one-hop and cannot distinguish the saved nonlocal witness; dense neighborhoods may make these local algorithms costly.",
      "rule": "weight / (1 + 0.75 * max(0, neighbor_greedy_weight) + 0.25 * max(0, neighbor_cover_weight)) + 0.05 * weight / (1 + max(0, duration))"
    },
