      ],
      "name": "residual_moment_continuation",
      "rationale": "Compresses compatible weight by normalized weighted conflict load in the root-conditioned residual to approximate continuation value. It observes edges beyond one hop, although this aggregate need not resolve the witness; inducing the full residual can be quadratic.",
      "rule": "weight + compatible_weight / (1 + 2 * max(0, residual_pair_pressure)) - 0.05 * conflict_weight / (1 + max(0, degree))"
    },
