          },
          "name": "cover_displacement"
        }
      ],
      "name": "global_cover_displacement",
      "rationale": "Estimates displaced opportunity by comparing covers after excluding only the root and after removing its closed neighborhood. Full active-graph partitions can respond to distant changes, but their difference is heuristic and two global cover computations may dominate runtime.",
      "rule": "weight - max(0, cover_displacement) + 0.1 * weight / (1 + max(0, degree))"
    },
