          },
          "name": "compatible_greedy_weight"
        }
      ],
      "name": "global_greedy_continuation",
      "rationale": "Ranks immediate reward plus a deterministic feasible greedy continuation over surviving compatible contacts. Root conditioning supplies nonlocal structure, but repeated global greedy passes can dominate the complete solve and witness repair is unverified.",
      "rule": "weight + compatible_greedy_weight + 0.02 * weight / (1 + max(0, degree))"
    },
